			dynWeights[0] = 2.5
			dynWeights[1] = 0.5
		} else {
			// Non-sessions: balance based on cluster load
			dynWeights[0] = 1.0 - 0.7*loadPressure
			dynWeights[1] = 1.0 + 1.5*loadPressure
		}
		wSum := dynWeights[0] + dynWeights[1]
		if wSum > 0.001 {
